//! `FunctionExprent` and `AssignmentExprent` over constant and static-field
//! leaves against Vineflower 1.12.0 (`data/b02/GenFunctionOracle.java` ->
//! `data/b02/function_golden.txt`, regenerated by `data/b02/gen.sh`):
//! `getExprType`, `getInferredExprType` and the casts it settles,
//! `checkExprTypeBounds` of every function and assignment node,
//! `getPrecedence`, `toJava` and its reformatted (newline-group) form, and
//! `MatchEngine` patterns over the trees (`Exprent.match`/`findObject` and the
//! `ConstExprent`/`FunctionExprent` overrides). The tree parser mirrors the
//! Java driver's, so construction order matches.
//!
//! Java keeps a match node's rules in a `HashMap` keyed by an enum, whose
//! iteration order (and so which variables a failing match has bound) is
//! arbitrary; variables are compared for successful matches only.
//!
//! A column whose Rust side reaches a body other slices have not ported yet
//! (`UnportedError`) is counted as blocked, not failed.

use std::path::Path;

use kuna_jvm::assignment_exprent::AssignmentExprent;
use kuna_jvm::byte_cursor::ByteCursor;
use kuna_jvm::classes_processor::{ClassNode, ClassNodeType};
use kuna_jvm::const_exprent::{ConstExprent, ConstValue};
use kuna_jvm::decompiler_context::DecompilerContext;
use kuna_jvm::exprent::Exprent;
use kuna_jvm::field_descriptor::FieldDescriptor;
use kuna_jvm::field_exprent::FieldExprent;
use kuna_jvm::function_exprent::{FunctionExprent, FunctionType};
use kuna_jvm::i_fernflower_preferences::IFernflowerPreferences;
use kuna_jvm::import_collector::ImportCollector;
use kuna_jvm::match_engine::MatchEngine;
use kuna_jvm::match_node::MatchValue;
use kuna_jvm::rt::jstring::from_utf16;
use kuna_jvm::struct_class::StructClass;
use kuna_jvm::text_buffer::TextBuffer;
use kuna_jvm::var_type::VarType;

use crate::b02_const_exprent::vartype;
use crate::common;
use crate::f2_types::{esc, run, same, unesc};

const GOLDEN: &str = include_str!("data/b02/function_golden.txt");

fn value(spec: &str) -> Option<ConstValue> {
    if spec == "N" {
        return None;
    }
    let v = &spec[2..];
    Some(match &spec[..1] {
        "I" => ConstValue::Int(v.parse().unwrap()),
        "J" => ConstValue::Long(v.parse().unwrap()),
        "F" => ConstValue::Float(f32::from_bits(u32::from_str_radix(v, 16).unwrap())),
        "D" => ConstValue::Double(f64::from_bits(u64::from_str_radix(v, 16).unwrap())),
        "S" => {
            let units: Vec<u16> = (1..v.len())
                .step_by(4)
                .map(|i| u16::from_str_radix(&v[i..i + 4], 16).unwrap())
                .collect();
            ConstValue::String(from_utf16(&units))
        }
        other => panic!("bad value spec {other}"),
    })
}

fn func_type(name: &str) -> FunctionType {
    *FunctionType::VALUES
        .iter()
        .find(|t| t.name() == name)
        .unwrap_or_else(|| panic!("unknown function type {name}"))
}

struct Parser {
    toks: Vec<String>,
    pos: usize,
}

impl Parser {
    fn build(tree: &str) -> Exprent {
        let spaced = tree.replace('(', " ( ").replace(')', " ) ");
        let mut parser = Parser {
            toks: spaced.split_whitespace().map(str::to_string).collect(),
            pos: 0,
        };
        parser.parse()
    }

    fn next(&mut self) -> String {
        self.pos += 1;
        self.toks[self.pos - 1].clone()
    }

    fn parse(&mut self) -> Exprent {
        let t = self.next();
        if t == "(" {
            let mut head = self.next();
            if let Some(cond) = head.strip_prefix('=') {
                let cond = (!cond.is_empty()).then(|| func_type(cond));
                let left = self.parse();
                let right = self.parse();
                self.pos += 1;
                return AssignmentExprent::new_cond(left, right, cond, None).0;
            }
            let mut implicit = None;
            if let Some(at) = head.find('@') {
                implicit = Some(head[at + 1..].to_string());
                head.truncate(at);
            }
            let no_cast = head.ends_with('!');
            if no_cast {
                head.pop();
            }
            let mut ops = Vec::new();
            while self.toks[self.pos] != ")" {
                ops.push(self.parse());
            }
            self.pos += 1;
            let f = FunctionExprent::new(func_type(&head), ops, None);
            if no_cast {
                f.set_needs_cast(false);
            }
            if let Some(implicit) = implicit {
                f.set_implicit_type(Some(vartype(&implicit)));
            }
            return f.0;
        }
        if let Some(rest) = t.strip_prefix('G') {
            let bool_permitted = rest.starts_with('1');
            return ConstExprent::new_int(rest[2..].parse().unwrap(), bool_permitted, None).0;
        }
        if let Some(sig) = t.strip_prefix("T:") {
            return ConstExprent::new(VarType::new_signature(sig), None, None).0;
        }
        if t.starts_with("FS:") || t.starts_with("FX:") {
            let p: Vec<&str> = t.split(':').collect();
            let class = if t.starts_with("FS:") {
                "b02/B02Fields"
            } else {
                p[1]
            };
            let (name, desc) = (p[p.len() - 2], p[p.len() - 1]);
            return FieldExprent::new(
                name.to_string(),
                class.to_string(),
                true,
                None,
                FieldDescriptor::parse_descriptor(desc),
                None,
            )
            .0;
        }
        let colon = 2 + t[2..].find(':').expect("C:TYPE:value");
        ConstExprent::new(vartype(&t[2..colon]), value(&t[colon + 1..]), None).0
    }
}

fn preorder(e: Exprent, out: &mut Vec<Exprent>) {
    out.push(e);
    for c in e.get_all_exprents() {
        preorder(c, out);
    }
}

fn index_of(all: &[Exprent], e: Exprent) -> i32 {
    all.iter().position(|&x| x == e).map_or(-1, |i| i as i32)
}

fn bounds(root: Exprent) -> String {
    let mut all = Vec::new();
    preorder(root, &mut all);
    let mut entries = Vec::new();
    for (i, &e) in all.iter().enumerate() {
        if !e.is_function() && !e.is_assignment() {
            continue;
        }
        let one = run(|| {
            let r = e.check_expr_type_bounds().expect("a result");
            let mut b = String::new();
            for p in r.get_lower_bounds() {
                b.push_str(&format!("L{}={},", index_of(&all, p.exprent), p.type_));
            }
            for p in r.get_upper_bounds() {
                b.push_str(&format!("U{}={},", index_of(&all, p.exprent), p.type_));
            }
            esc(Some(&b))
        });
        entries.push(format!("{i}:{one}"));
    }
    entries.join(" | ")
}

fn match_row(f: &[&str], rows: &mut Rows) {
    let tree = f[1];
    let what: String = tree.chars().take(160).collect();
    let pattern = unesc(f[2]).expect("pattern");
    let lines: Vec<&str> = pattern.split('|').collect();
    DecompilerContext::start_class(ImportCollector::new(
        DecompilerContext::get_current_class_node().expect("node"),
    ));
    let e = Parser::build(tree);
    let mut engine = None;
    let result = run(|| {
        let made = MatchEngine::new(&lines);
        let matched = made.match_(&e);
        engine = Some(made);
        matched.to_string()
    });
    rows.check(&what, "match", f[3], &result);
    if f[3] != "true" || result != "true" {
        return;
    }

    let mut names: Vec<String> = Vec::new();
    for part in pattern.split('$').skip(1).step_by(2) {
        let name = format!("${part}$");
        if !names.contains(&name) {
            names.push(name);
        }
    }
    names.sort();
    let mut vars = String::new();
    for name in &names {
        let text = run(|| {
            let v = engine.as_ref().and_then(|en| en.get_variable_value(name));
            match v {
                None => "N".to_string(),
                Some(MatchValue::Exprent(x)) => format!(
                    "E:{}",
                    esc(Some(
                        &x.to_java(0).convert_to_string_and_allow_data_discard()
                    ))
                ),
                Some(other) => format!("O:{}", esc(Some(&other.to_java_string()))),
            }
        });
        vars.push_str(&format!("{name}={text},"));
    }
    rows.check(&what, "variables", &unesc(f[4]).expect("vars"), &vars);
}

fn type_text(t: Option<VarType>) -> String {
    t.map_or("null".to_string(), |t| t.to_string())
}

struct Rows {
    checked: usize,
    blocked: usize,
    failures: Vec<String>,
}

impl Rows {
    fn check(&mut self, what: &str, column: &str, java: &str, rust: &str) {
        if rust.starts_with("EXC:UnportedError:") {
            self.blocked += 1;
            return;
        }
        self.checked += 1;
        if !same(java, rust) {
            self.failures.push(format!(
                "{what} [{column}]\n   java: {java}\n   rust: {rust}"
            ));
        }
    }

    fn check_bounds(&mut self, what: &str, java: &str, rust: &str) {
        let java = unesc(java).expect("bounds");
        let rust = unesc(rust).expect("bounds");
        let java_entries: Vec<&str> = java.split(" | ").collect();
        let rust_entries: Vec<&str> = rust.split(" | ").collect();
        if java_entries.len() != rust_entries.len() {
            self.checked += 1;
            self.failures
                .push(format!("{what} [bounds]\n   java: {java}\n   rust: {rust}"));
            return;
        }
        for (j, r) in java_entries.iter().zip(rust_entries.iter()) {
            let (jn, jv) = j.split_once(':').unwrap_or((j, ""));
            let (rn, rv) = r.split_once(':').unwrap_or((r, ""));
            if jn != rn {
                self.checked += 1;
                self.failures
                    .push(format!("{what} [bounds node]\n   java: {j}\n   rust: {r}"));
                continue;
            }
            self.check(what, "bounds", jv, rv);
        }
    }
}

#[test]
fn function_exprent_matches_vineflower() {
    let _guard =
        common::install_context_with(&[(IFernflowerPreferences::PREFERRED_LINE_LENGTH, "40")]);
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/b02/b02/B02Fields.class");
    let bytes = std::fs::read(path).expect("B02Fields.class");
    let cl = StructClass::create(&mut ByteCursor::new(bytes), true);
    let node = ClassNode::new(ClassNodeType::Root, cl);
    DecompilerContext::set_current_class_node(Some(node));
    DecompilerContext::set_current_class(Some(cl));
    let fresh = || DecompilerContext::start_class(ImportCollector::new(node));

    let mut rows = Rows {
        checked: 0,
        blocked: 0,
        failures: Vec::new(),
    };
    for line in GOLDEN.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        if f[0] == "M" {
            match_row(&f, &mut rows);
            continue;
        }
        assert_eq!(f[0], "F");
        let tree = f[1];
        let what: String = tree.chars().take(160).collect();

        fresh();
        let e = Parser::build(tree);
        let expr_type = run(|| esc(Some(&type_text(e.get_expr_type_opt()))));
        let bnds = run(|| esc(Some(&bounds(e))));
        fresh();
        let prec = run(|| e.get_precedence().to_string());
        fresh();
        let mut buf: Option<TextBuffer> = None;
        let text = run(|| {
            let b = e.to_java(0);
            let s = b.convert_to_string_and_allow_data_discard();
            buf = Some(b);
            esc(Some(&s))
        });
        let reformatted = match buf {
            None => text.clone(),
            Some(mut b) => run(move || {
                b.reformat();
                esc(Some(&b.convert_to_string_and_allow_data_discard()))
            }),
        };

        fresh();
        let e2 = Parser::build(tree);
        let inferred = run(|| esc(Some(&type_text(e2.get_inferred_expr_type_opt(None)))));
        fresh();
        let inferred_text = run(|| {
            esc(Some(
                &e2.to_java(0).convert_to_string_and_allow_data_discard(),
            ))
        });

        rows.check(&what, "exprType", f[2], &expr_type);
        rows.check(&what, "inferred", f[3], &inferred);
        rows.check(&what, "inferredText", f[4], &inferred_text);
        rows.check_bounds(&what, f[5], &bnds);
        rows.check(&what, "precedence", f[6], &prec);
        rows.check(&what, "toJava", f[7], &text);
        rows.check(&what, "reformatted", f[8], &reformatted);
    }

    eprintln!(
        "FunctionExprent columns: {} checked, {} blocked on unported bodies",
        rows.checked, rows.blocked
    );
    assert!(
        rows.checked > 5_000,
        "only {} columns checked",
        rows.checked
    );
    assert!(
        rows.failures.is_empty(),
        "{} mismatches:\n{}",
        rows.failures.len(),
        rows.failures
            .iter()
            .take(30)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
